  {
   "oldText": "    # Split panels at the all-zero divider. Their shared color is the canvas;
    # coincident cells of that color become 3.
    sep = next(c for c in range(w) if all(row[c] == 0 for row in grid))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    common = set(v for row in left for v in row) & set(v for row in right for v in row)
    color = next(iter(common))
    return [[3 if left[r][c] == color and right[r][c] == color else color
             for c in range(min(len(left[r]), len(right[r])))] for r in range(h)]",
   "newText": "    # The repeated 2s mark the boundary between two panels. Combine the
    # colored pattern on the left with the binary mask on the right.
    sep = next(c for c in range(w) if all(row[c] == 2 for row in grid))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    # The left mosaic uses colors 5/7; the right mask uses 0/5.
    # Paint a 7 wherever the right-side mask is occupied; retain 5 otherwise.
    out = []
    for r in range(h):
        row = []
        for c in range(min(len(left[r]), len(right[r]))):
            row.append(7 if right[r][c] == 5 else 5)
        out.append(row)
    return out"
  }
 ]
